CREATE OR REPLACE FUNCTION public.prevent_supervisor_operational_changes() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF public.is_read_only_supervisor() THEN RAISE EXCEPTION 'Supervisors have read-only access' USING ERRCODE='42501'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['dams','movements','loads','trucks','dam_adjustments','dam_transactions','settings','user_roles','reports','report_versions','report_audit_log'] LOOP EXECUTE format('CREATE TRIGGER supervisor_read_only BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.prevent_supervisor_operational_changes()',t); END LOOP; END $$;
CREATE POLICY "Supervisors read report files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='reports' AND public.is_read_only_supervisor());
CREATE POLICY "Supervisors cannot upload files" ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (NOT public.is_read_only_supervisor());
CREATE POLICY "Supervisors cannot change files" ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING (NOT public.is_read_only_supervisor()) WITH CHECK (NOT public.is_read_only_supervisor());
CREATE POLICY "Supervisors cannot delete files" ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING (NOT public.is_read_only_supervisor());